"const fs = require('fs');
const path = require('path');
const readline = require('readline');

const logFile = 'C:\\Users\\acer\\.gemini\\antigravity-ide\\brain\\2de7bcaa-0beb-4e39-a212-ed32f0415aba\\.system_generated\\logs\\transcript.jsonl';

const rl = readline.createInterface({
  input: fs.createReadStream(logFile),
  crlfDelay: Infinity
});

let lastBrowserCall = null;

rl.on('line', (line) => {
  if (line.includes('browser_subagent')) {
    lastBrowserCall = line;
  }
});

rl.on('close', () => {
  if (lastBrowserCall) {
    console.log('Found browser subagent line! Length:', lastBrowserCall.length);
    try {
      const parsed = JSON.parse(lastBrowserCall);
      console.log('Type:', parsed.type);
      console.log('Status:', parsed.status);
      if (parsed.content) {
        console.log('Content snippet:', parsed.content.substring(0, 1000));
      }
      if (parsed.tool_calls) {
        console.log('Tool calls:', JSON.stringify(parsed.tool_calls, null, 2).substring(0, 1000));
      }
      // If it's a tool output, look for the result
      fs.writeFileSync('subagent_output.json', JSON.stringify(parsed, null, 2));
      console.log('Wrote parsed JSON to subagent_output.json');
    } catch (e) {
      console.error('Error parsing JSON:', e.message);
      fs.writeFileSync('subagent_raw.txt', lastBrowserCall);
    }
  } else {
    console.log('No browser_subagent found.');
  }
});
"
